/* One learning flow, two explicitly separated cube sources. */
const LessonFlow=(()=>{
const VERSION='cube-consistent-v1',PHASES=['기준색 확인','목표 조각 찾기','보낼 자리 확인','시범 보기','직접 적용','결과 확인'],TITLES=['흰 꽃','흰 십자','1층 코너','2층 엣지','노란 십자','노란 면','코너 자리','엣지 자리'];
const E=[[5,10],[7,19],[3,37],[1,46],[32,16],[28,25],[30,43],[34,52],[23,12],[21,41],[50,39],[48,14]],C=[[8,9,20],[6,18,38],[0,36,47],[2,45,11],[29,26,15],[27,44,24],[33,53,42],[35,17,51]],EC=['UR','UF','UL','UB','DR','DF','DL','DB','FR','FL','BL','BR'],CC=['URF','UFL','ULB','UBR','DFR','DLF','DBL','DRB'];
let state=null,model=null,view='auto',job=null,moving=false,loading='',error='',menu=false,chosenFace=null;
function read(mode){try{let o=JSON.parse(localStorage.getItem(VERSION+'-'+mode)||'null');return o&&o.mode===mode&&o.current?.length===54?o:null;}catch{return null;}}
try{let m=localStorage.getItem(VERSION+'-mode');state=read(m==='camera'?'camera':'sample');}catch{}
function save(){if(!state)return;try{localStorage.setItem(VERSION+'-'+state.mode,JSON.stringify(state));localStorage.setItem(VERSION+'-mode',state.mode);}catch{}}
function fixedEdges(c,ids){return ids.every(i=>c.ep[i]===i&&c.eo[i]===0);}
function fixedCorners(c,ids){return ids.every(i=>c.cp[i]===i&&c.co[i]===0);}
const lower=c=>fixedEdges(c,[4,5,6,7,8,9,10,11])&&fixedCorners(c,[4,5,6,7]);
function milestone(c,n){if(n===0)return[4,5,6,7].every(p=>{let i=c.ep.indexOf(p);return i<4&&c.eo[i]===0;});if(n===1)return fixedEdges(c,[4,5,6,7]);if(n===2)return milestone(c,1)&&fixedCorners(c,[4,5,6,7]);if(n===3)return lower(c);if(n===4)return lower(c)&&c.eo.slice(0,4).every(v=>v===0);if(n===5)return milestone(c,4)&&c.co.slice(0,4).every(v=>v===0);if(n===6)return milestone(c,5)&&c.cp.every((p,i)=>p===i);return c.isSolved();}
function detect(c){if(c.isSolved())return 8;for(let n=6;n>=1;n--)if(milestone(c,n))return n+1;return milestone(c,0)?1:0;}
function fresh(mode,str,start){const c=valid(str);return{mode,initial:str,current:str,initiallySolved:c.isSolved(),stage:start??detect(c),phase:0,prep:0,hold:[],edgeFound:false,plan:null,demoPos:0,practice:null,history:[],picked:false,goalPicked:false,basis:false,understood:false,feedback:'',completed:[],revision:0};}
function routeToLesson(){if(location.hash==='#learn')render();else location.hash='#learn';}
function openExample(start){save();let existing=read('sample');if(start===undefined&&existing){state=existing;restore();routeToLesson();return;}let str=new Cube().move("R U R' U' F U F' U' L'").asString();if(start===1)str=new Cube().move("F2 R2 B2 L2 U'").asString();state=fresh('sample',str,start??0);restore();routeToLesson();}
function openCaptured(str){try{valid(str);}catch(e){scanError=e.message;render();return;}save();state=fresh('camera',str);restore();routeToLesson();}
function switchMode(mode){if(moving||loading||state?.mode===mode)return;save();let other=read(mode);if(other){state=other;restore();render();}else if(mode==='sample')openExample();else location.hash='#scan';}
function restore(){if(job){job.terminate();job=null;}loading='';error='';view='auto';model=state?Cube.fromString(state.phase===4||state.phase===5?state.practice||state.current:state.current):null;if(state&&state.phase===3&&state.plan){const seg=segment();model=Cube.fromString(state.current).move(moves().slice(0,state.demoPos).join(' '));}if(state&&[3,4].includes(state.phase))view=state.lockedView||'auto';save();if(state&&state.stage<8&&!state.plan)prepare();}
function prepare(){if(!state||state.stage>=8)return;const origin=state.current,revision=++state.revision;loading='같은 큐브 상태에서 다음 조각의 수업을 준비하고 있어요.';error='';job=new Worker('worker.js');const timeout=setTimeout(()=>{if(!job)return;job.terminate();job=null;loading='';error='수업 준비 시간이 길어졌어요. 현재 큐브 상태는 보관되어 있어요. 다시 준비해주세요.';render();},45000);job.onmessage=e=>{if(e.data.type==='progress')return;if(!state||state.revision!==revision)return;clearTimeout(timeout);job.terminate();job=null;loading='';if(e.data.type==='error'){error=e.data.message;render();return;}state.plan=e.data.stages;while(state.stage<8&&!state.plan[state.stage].moves.length){state.completed.push(state.stage);state.stage++;}state.phase=0;state.demoPos=0;state.practice=null;state.history=[];state.picked=false;state.goalPicked=false;state.basis=false;state.understood=false;state.feedback='';model=Cube.fromString(origin);save();if(route==='learn')render();};job.onerror=()=>{clearTimeout(timeout);job?.terminate();job=null;loading='';error='수업을 준비하지 못했어요. 현재 상태를 유지한 채 다시 시도할 수 있어요.';render();};job.postMessage({facelets:origin,startStage:state.stage});}
function stage(){return state.plan[state.stage];}
function segment(){return stage().segments[0];}
function moves(){const seg=segment();return stage().moves.slice(seg.start,seg.end);}
function descriptor(){const seg=segment();if(seg.piece!=null)return{piece:seg.piece,kind:seg.kind};return{kind:[5,6].includes(state.stage)?'corner':'edge',piece:null};}
function targetColors(){const d=descriptor();return d.piece==null?'노란색 조각들':(d.kind==='corner'?CC:EC)[d.piece].split('').map(f=>NAMES[f]).join('·');}
function basisFace(){if(state.stage===0||state.stage>=4)return'U';const d=descriptor(),cs=(d.kind==='corner'?CC:EC)[d.piece];if(state.stage===2)return'D';return[...cs].find(f=>f!=='D'&&f!=='U')||'F';}

function targetIndices(c=model){const d=descriptor();if(d.piece!=null)return(d.kind==='corner'?C:E)[(d.kind==='corner'?c.cp:c.ep).indexOf(d.piece)];return(d.kind==='corner'?C:E).slice(0,4).flat();}
function destination(){const d=descriptor();if(state.stage===0){const end=Cube.fromString(segment().final);return E[end.ep.indexOf(d.piece)];}if(state.stage===1)return E[d.piece-4];if(d.piece!=null)return(d.kind==='corner'?C:E)[d.piece];return(d.kind==='corner'?C:E).slice(0,4).flat();}
function segmentGoal(c,n,d,initial){if(n===0){const isPetal=(x,p)=>{let i=x.ep.indexOf(p);return i<4&&x.eo[i]===0;};return isPetal(c,d.piece)&&[4,5,6,7].filter(p=>isPetal(initial,p)).every(p=>isPetal(c,p));}if(n===1){const fixed=[4,5,6,7].filter(i=>initial.ep[i]===i&&initial.eo[i]===0);const locked=[d.piece,...fixed],remaining=[4,5,6,7].filter(p=>!locked.includes(p));return fixedEdges(c,locked)&&remaining.every(p=>{const i=c.ep.indexOf(p);return i<4&&c.eo[i]===0;});}if(n===2){const fixed=[4,5,6,7].filter(i=>initial.cp[i]===i&&initial.co[i]===0);return milestone(c,1)&&fixedCorners(c,[d.piece,...fixed]);}if(n===3){const fixed=[8,9,10,11].filter(i=>initial.ep[i]===i&&initial.eo[i]===0);return milestone(c,2)&&fixedEdges(c,[d.piece,...fixed]);}return milestone(c,n);}
function practiceGoal(c){return segmentGoal(c,state.stage,descriptor(),Cube.fromString(state.current));}
function header(){return`<div class="source-bar"><div class="source-choices"><button data-source="sample" aria-pressed="${state?.mode==='sample'}">예제 큐브</button><button data-source="camera" aria-pressed="${state?.mode==='camera'}">내 촬영 큐브</button></div><div class="source-status"><b>${state?.mode==='camera'?'내가 촬영한 상태를 이어가는 중':state?'준비된 예제로 배우는 중':'학습할 큐브를 선택해주세요'}</b>${state?'<button class="text-btn" id="source-state">출발한 6면 보기</button>':''}</div></div>`;}
function shell(title,sub,content){return header()+heading('한 조각씩, 같은 순서로 배우는 큐브 수업',title,sub)+content;}
function chooser(){return shell('어떤 큐브로 배워볼까요?','수업 순서는 같고, 출발하는 큐브와 진도만 달라요.',`<div class="source-cards"><section class="panel"><span class="kicker">예제 큐브</span><h2>준비된 배치로 원리부터</h2><p class="muted">처음 잡는 법부터 흰·주황 엣지 하나를 꽃잎으로 올려요. 다음 색도 같은 방식으로 반복합니다.</p><button class="primary orange" id="choose-example">예제로 첫 수업 시작 →</button></section><section class="panel"><span class="kicker">내 촬영 큐브</span><h2>지금 손에 든 상태 그대로</h2><p class="muted">6면을 등록한 배치에서 시작합니다. 맞춘 부분은 유지하고, 내가 돌린 결과에서 다음 수업을 이어가요.</p><a class="primary" href="#scan">내 큐브 6면 등록 →</a></section></div>`);}
function focusBoard(){document.querySelector('.first-board')?.scrollIntoView({block:'start',behavior:'auto'});}
function colorsOf(c,indices){return[...new Set(indices.map(i=>NAMES[c.asString()[i]]))].join('·');}
function cameraForFace(f){const down=f.endsWith('-low');f=f.replace('-low','');return f==='U'?'rotateX(-75deg) rotateY(0deg)':f==='D'?'rotateX(75deg) rotateY(0deg)':`rotateX(${down?24:-24}deg) rotateY(${{F:-25,R:-115,L:65,B:155}[f]}deg)`;}
function autoFace(){if(state.prep===0)return'F';if(state.prep===1)return'F';if(state.phase===0)return basisFace();if(state.phase===2){const i=destination().find(i=>state.stage===0?i<9:Math.floor(i/9)===FACES.indexOf(basisFace()))??destination()[0];return FACES[Math.floor(i/9)];}const d=descriptor();if(d.piece!=null){const pos=(d.kind==='corner'?model.cp:model.ep).indexOf(d.piece),face=d.kind==='corner'?['F','L','B','R','F','L','B','R'][pos]:['R','F','L','B','R','F','L','B','F','L','B','R'][pos];return face+((d.kind==='corner'?pos>=4:pos>=4&&pos<8)?'-low':'');}return'U';}
function viewButtons(){return`<div class="flow-views">${[['auto','중점 보기'],['F','앞'],['R','오른쪽'],['L','왼쪽'],['B','뒤'],['U','위'],['D','아래']].map(([f,t])=>`<button data-flow-view="${f}">${t}</button>`).join('')}</div>`;}
function lessonGoal(){if(state.stage===0)return`${targetColors()} 엣지의 흰색을 노란 중심 옆에 올려 꽃잎으로 만들어요. 옆 색은 아직 중심과 맞추지 않아도 돼요.`;if(state.stage===1)return`${targetColors()} 엣지의 옆 색을 같은 색 중심 바로 위에 맞춰요. 그 색 면을 반 바퀴 돌려 흰 중심 쪽으로 내려요. 아직 내리지 않은 다른 흰 꽃잎은 위에 남겨요.`;if(state.stage===2)return`${targetColors()} 코너를 같은 세 색의 중심이 만나는 자리에 넣어요. 이미 맞춘 흰 십자도 지켜요.`;if(state.stage===3)return`${targetColors()} 엣지를 두 중심 사이에 넣고, 아래 1층을 복구해요.`;return stage().principle;}
function actionNarration(){if(state.feedback)return state.feedback;if(state.prep===0)return state.hold.includes('U')?'초록 가운데 칸을 눌러 앞면도 확인하세요. 노란 중심은 계속 위를 향해요.':'노란 중심은 위, 초록 중심은 나를 향하게 잡아요. 먼저 화면의 노란 가운데 칸을 눌러보세요.';if(state.prep===1)return'면 한가운데는 한 색의 중심, 모서리 끝은 세 색의 코너예요. 변 가운데에 있는 두 색의 엣지를 하나 눌러보세요.';if(state.phase===0)return`${NAMES[basisFace()]} 중심을 찾아 눌러보세요. ${state.stage===0?'꽃잎이 모일 기준은 노란 중심이에요.':state.stage===1?'이 색과 흰색이 붙은 엣지를 이 중심에 연결할 거예요.':'중심색이 조각이 들어갈 자리를 알려줘요.'}`;if(state.phase===1)return`${targetColors()} ${descriptor().kind==='corner'?'코너':'엣지'}를 찾아 눌러보세요. ${state.stage===0||state.stage===1?'이 조각도 꽃에서는 위로 모으고, 십자에서는 옆 색을 맞춰 아래로 내려요.':''}`;if(state.phase===2){if(state.stage===1){const d=descriptor(),p=model.ep.indexOf(d.piece),aligned=p===d.piece-4&&model.eo[p]===0;return aligned?`${targetColors()}의 옆 색은 이미 ${NAMES[basisFace()]} 중심 위에 맞아 있어요. 윗면을 더 돌릴 필요 없이 그 색 면을 반 바퀴 내리면 돼요. 표시한 칸을 눌러 확인하세요.`:`옆 색은 지금 ${NAMES[['R','F','L','B'][p]]} 중심 쪽에 있어요. ${NAMES[basisFace()]} 중심 바로 위가 먼저 맞출 자리예요. 표시한 칸을 눌러보세요.`;}return lessonGoal()+' 테두리로 표시한 도착 칸을 눌러 확인하세요.';}if(state.phase===3){let m=moves()[state.demoPos];if(!m)return'묶음 동작이 끝났어요. 목표 모양과 이미 맞춘 부분이 함께 유지됐는지 관찰하세요.';if(state.stage===1)return m[0]==='U'?`윗면만 돌려 ${targetColors()}의 옆 색을 같은 중심 바로 위에 맞춰요. 흰색은 계속 위를 향해요.`:`옆 색이 중심과 맞았으니 ${FACE_NAMES[m[0]]}을 반 바퀴 내려요. 흰색은 아래 흰 중심 옆으로, 옆 색은 자기 중심 옆으로 함께 가요.`;if(state.stage===0){const d=descriptor(),a=model.ep.indexOf(d.piece),b=model.clone().move(m).ep.indexOf(d.piece);return a===b?'목표 엣지는 잠시 두고, 이미 올린 꽃잎을 피하거나 올릴 빈자리를 준비해요.':`${targetColors()} 두 색은 한 조각으로 함께 움직여요. ${describe(m).short}. 흰색이 어디를 향하는지 따라가보세요.`;}return segment().why;}if(state.phase===4)return practiceGoal(model)?'목표가 만들어졌어요. 같은 조각의 다른 색과 이미 맞춘 부분도 확인해보세요.':'이제 직접 옮겨보세요. 정해진 버튼 순서와 비교하지 않고 실제 조각의 결과로 확인해요. 틀리면 한 수 되돌려 다시 관찰할 수 있어요.';return lessonGoal();}
function coach(){const m=state.prep>=2&&state.phase===3?moves()[state.demoPos]:null;return`<div class="cube-coach intro-coach" role="status" aria-live="polite"><span class="coach-avatar">✳</span><div><small>${state.prep<2?'준비 · '+(state.prep===0?'같은 방향으로 잡기':'조각 구분하기'):PHASES[state.phase]}</small><b>${m?describe(m).short:state.prep<2?'아직 면을 돌리지 않아요':state.phase===3?'시범은 보기만 하세요':state.phase===4?'내가 선택한 수대로 움직여요':PHASES[state.phase]}</b><p>${actionNarration()}</p></div></div>`;}
function board(){return`<div class="lesson-stage with-coach intro-stage flow-stage">${coach()}<div class="intro-cube-slot">${cubeHTML(model.asString(),'flow-cube')}</div>${viewButtons()}<span class="stage-caption">보기 버튼은 보는 방향만 바꿔요. 실제 회전은 아래 조작 버튼으로 해요.</span></div>`;}
function prepPage(){return shell(state.prep===0?'먼저, 같은 방향으로 잡아요.':'스티커가 아니라 한 조각을 찾아요.',state.mode==='camera'?'화면의 큐브는 촬영한 내 상태 그대로예요.':'이 예제 큐브로 잡는 법부터 배워요.',`<div class="first-course"><section class="panel first-board">${board()}<div class="pick-state">${state.prep===0?state.hold.includes('U')&&state.hold.includes('F')?'✓ 위와 앞을 확인했어요.':'노랑 위 → 초록 앞. 두 중심을 차례로 눌러주세요.':state.edgeFound?'✓ 두 색이 한 몸인 엣지를 찾았어요.':'화면에서 두 색이 붙은 엣지를 하나 눌러주세요.'}</div></section><section class="panel first-notes"><span class="kicker">출발 상태를 바꾸지 않는 준비 수업</span><h2>${state.prep===0?'중심으로 방향을 정해요.':'중심 1색 · 엣지 2색 · 코너 3색'}</h2><p class="muted">${state.prep===0?'노란 가운데 칸이 천장을 보고, 초록 가운데 칸이 나를 보게 잡아요. 손은 양옆을 가볍게 잡습니다. 이후 화면의 보는 방향이 달라져도 중심 이름은 그대로예요.':'엣지의 두 색은 떨어져 움직이지 않아요. 한 면을 돌리면 그 층에 걸친 조각들이 함께 이동해요. 중심색은 조각이 들어갈 자리를 찾는 기준입니다.'}</p><div class="source-integrity">${state.mode==='camera'?'촬영한 배치를 유지하고 있어요. 준비 수업에서 큐브를 섞지 않습니다.':'같은 예제 배치가 꽃 → 십자 → 다음 층으로 계속 이어집니다.'}</div><button class="primary orange first-next" id="flow-prep-next" ${!(state.prep===0?state.hold.includes('U')&&state.hold.includes('F'):state.edgeFound)?'disabled':''}>${state.prep===0?'이 방향으로 잡았어요 →':'한 조각씩 수업 시작 →'}</button></section></div>`);}
function phases(){return`<div class="first-course-progress flow-progress">${PHASES.map((p,i)=>`<span class="${i===state.phase?'current':i<state.phase?'finished':''}"><i>${i<state.phase?'✓':i+1}</i>${p}</span>`).join('')}</div>`;}
function practiceControls(){let faces=[...new Set([...moves().map(m=>m[0]),basisFace()])];if(menu)faces=FACES;const mobileFace=faces.includes(chosenFace)?chosenFace:faces[0];return`<div class="flow-turns" id="flow-desktop">${faces.map(f=>`<div><b>${NAMES[f]} · ${FACE_NAMES[f]}</b><div>${['',"'",'2'].map(s=>`<button data-flow-turn="${f+s}" ${practiceGoal(model)?'disabled':''}>${s==="'"?'↶ 왼쪽 90°':s==='2'?'반 바퀴 180°':'↷ 오른쪽 90°'}</button>`).join('')}</div></div>`).join('')}</div><div class="flow-mobile-dock" id="flow-mobile"><div class="flow-face-picks">${faces.map(f=>`<button data-flow-face="${f}" class="${f===mobileFace?'selected':''}">${NAMES[f]} ${FACE_NAMES[f]}</button>`).join('')}</div><div class="flow-mobile-moves">${['',"'",'2'].map(s=>`<button data-flow-turn="${mobileFace+s}" ${practiceGoal(model)?'disabled':''}>${s==="'"?'↶ 왼쪽 90°':s==='2'?'반 바퀴 180°':'↷ 오른쪽 90°'}</button>`).join('')}</div></div><p class="turn-caption">방향은 돌릴 면을 정면에서 볼 때 기준이에요. ${state.mode==='camera'?'손의 큐브에도 같은 수를 적용하세요.':'예제는 화면에서만 조작해도 괜찮아요.'}</p><div class="intro-tools"><button class="text-btn" id="flow-undo" ${!state.history.length?'disabled':''}>↶ 한 수 되돌리기</button><button class="text-btn" id="flow-more">${menu?'필요한 면만 보기':'다른 면도 돌리기'}</button><button class="text-btn" id="flow-redemo">시범 다시 보기</button></div>`;}
function controls(){if(state.phase===3)return`<div class="button-row intro-controls"><button class="primary orange" id="flow-demo" ${state.demoPos>=moves().length?'disabled':''}>${state.demoPos<moves().length?'▷ 이 한 수 시범 보기':'시범 동작 완료'}</button><span class="demo-count">${state.demoPos} / ${moves().length}수</span></div>`;if(state.phase===4)return practiceControls();return`<div class="pick-state">${state.phase===0?state.basis?'✓ 기준 중심을 확인했어요.':'가운데 칸을 직접 눌러주세요.':state.phase===1?state.picked?'✓ 옮길 조각을 찾았어요.':'목표 조각을 직접 골라주세요.':state.phase===2?state.goalPicked?'✓ 보낼 자리를 확인했어요.':'표시된 도착 칸을 눌러주세요.':'목표를 만든 큐브 상태가 다음 조각의 출발 상태가 됩니다.'}</div>`;}
function nextReady(){return state.phase===0?state.basis:state.phase===1?state.picked:state.phase===2?state.goalPicked:state.phase===3?state.demoPos>=moves().length:state.phase===4?practiceGoal(model):state.understood;}
function path(){const d=descriptor(),cs=d.piece==null?'노란 조각':targetColors();return`<div class="cross-pattern flow-pattern"><span>${NAMES[basisFace()]} 중심 확인</span><b>→</b><span>${cs} ${d.kind==='corner'?'코너':'엣지'} 찾기</span><b>→</b><span>${state.stage===0?'노란 중심 옆으로':state.stage===1?'옆 색 정렬 → 반 바퀴 아래로':'같은 중심색이 만나는 자리로'}</span></div>`;}
function page(){if(!state)return chooser();if(loading)return shell('현재 큐브에 맞춰 다음 조각을 준비해요.','출발한 큐브와 이미 맞춘 부분을 유지합니다.',`<div class="panel loading" role="status">${loading}</div>`);if(error)return shell('현재 상태는 보관되어 있어요.','배치를 바꾸지 않고 다시 준비할 수 있어요.',`<div class="panel"><p class="error">${error}</p><button class="primary" id="flow-retry">다시 준비하기</button></div>`);if(state.stage>=8)return shell('지금 큐브의 여섯 면을 확인해보세요.','어떤 색의 조각을 어느 중심 사이로 보냈는지 떠올려보세요.',`<div class="panel"><h2>${state.initiallySolved?'등록한 큐브는 이미 완성된 상태예요.':state.mode==='camera'?'내 큐브 상태에서 완성했어요.':'같은 예제를 이어서 완성했어요.'}</h2><p class="muted">꽃은 노란 중심 주위의 준비 상태, 흰 십자는 흰 중심과 옆 색까지 맞춘 상태예요. 한 조각씩 같은 순서로 확인해왔어요.</p><button class="primary orange" id="flow-new-example">예제 처음부터 다시 배우기</button><a class="secondary" href="#scan">새 큐브 촬영하기</a></div>`);if(!state.plan)return shell('현재 상태를 읽고 있어요.','같은 상태에서 수업을 이어갑니다.','<div class="panel loading">수업 준비 중…</div>');if(state.prep<2)return prepPage();let q=quizzes[state.stage];return shell(`${String(state.stage+1).padStart(2,'0')}. ${stage().title}`,`${targetColors()} ${descriptor().kind==='corner'?'코너':'엣지'} · 색이 바뀌어도 확인하는 순서는 같아요.`, `<div class="consistent-curriculum">${TITLES.map((t,i)=>`<span class="${i===state.stage?'current':i<state.stage?'finished':''}">${i<state.stage?'✓':i+1} ${t}</span>`).join('')}</div>${phases()}<div class="first-course"><section class="panel first-board"><div class="stage-top"><span class="stat-pill">${state.phase===3?'보기만 하는 시범 · 실제 진도에 반영되지 않아요':state.phase===4?'직접 적용 · 이 결과에서 계속 이어가요':targetColors()+' · 같은 조각을 끝까지 확인해요'}</span></div>${board()}${controls()}</section><section class="panel first-notes"><span class="kicker">${PHASES[state.phase]}</span><h2>${state.phase===0?'무슨 색을 기준으로 볼까요?':state.phase===1?'어느 조각을 옮길까요?':state.phase===2?'그 조각을 어디로 보낼까요?':state.phase===3?'왜 이 면을 돌리는지 보세요.':state.phase===4?'이제 직접 그 자리에 보내보세요.':'맞은 이유를 말할 수 있나요?'}</h2><p class="muted">${lessonGoal()}</p>${path()}<div class="source-integrity">${state.phase===3?(state.resumePractice?'참고 시범 중에도 진행 중인 상태는 그대로 보관해요. 시범을 마치면 방금 조작하던 상태로 돌아옵니다.':'지금은 화면의 시범만 보세요. 손의 큐브는 아직 돌리지 않습니다. 직접 적용에서 같은 출발 상태로 돌아옵니다.'):state.mode==='camera'?'내 촬영 상태를 이어가는 수업입니다. 임의의 다른 문제 배치로 바꾸지 않아요.':'이 예제의 현재 상태가 다음 조각과 다음 단계까지 이어집니다.'}</div>${state.stage<=1?'<div class="flower-cross-distinction"><b>꽃 → 흰 십자, 목표를 구분해요.</b><p>꽃은 노란 중심 주위에 흰 엣지를 모으는 준비.<br>흰 십자는 옆 색을 중심에 맞추고 흰 중심 쪽으로 내린 결과예요.</p></div>':''}${state.phase===5?`<div class="quiz"><b>${q.q}</b>${q.a.map((a,i)=>`<button data-flow-answer="${i}">${a}</button>`).join('')}<p role="status">${state.feedback||'모양과 원리를 함께 확인해요.'}</p></div>`:''}<button class="primary orange first-next" id="flow-next" ${!nextReady()?'disabled':''}>${state.phase===5?'이 상태에서 다음 조각으로 →':state.phase===3?(state.resumePractice?'보관한 진행 상태로 돌아가기 →':'같은 출발 상태에서 직접 적용 →'):state.phase===4?'결과와 원리 확인 →':PHASES[state.phase+1]+' →'}</button><p class="first-pacing">같은 조각을 끝까지 보고, 다음 색도 같은 순서로.</p></section></div>`);}
function decorate(){const el=document.getElementById('flow-cube');if(!el)return;const face=view==='auto'?autoFace():view;el.style.transform=cameraForFace(face);const tiles=[...el.querySelectorAll('.sticker')],targets=state.prep>=2?targetIndices():[],dest=state.prep>=2?destination():[];tiles.forEach((t,i)=>{const f=FACES[Math.floor(i/9)],isEdge=E.findIndex(a=>a.includes(i)),isCorner=C.findIndex(a=>a.includes(i)),type=isEdge>=0?'엣지':isCorner>=0?'코너':'중심',ids=isEdge>=0?E[isEdge]:isCorner>=0?C[isCorner]:[i],text=i%9===4?NAMES[f]+' 중심':FACE_NAMES[f]+' '+(Math.floor(i%9/3)+1)+'행 '+(i%3+1)+'열 · '+colorsOf(model,ids)+' '+type;t.setAttribute('aria-label',text);t.setAttribute('role','button');t.setAttribute('tabindex','0');if(state.prep>=2&&state.phase>=2&&state.phase!==4&&targets.includes(i)){t.classList.add('first-target');t.innerHTML='<span>◎</span>';}if(state.prep>=2&&state.phase===2&&dest.includes(i)){t.classList.add('flow-destination');t.innerHTML='<span>여기</span>';}if(state.prep>=2&&state.phase===0&&i===FACES.indexOf(basisFace())*9+4){t.classList.add('cross-center');t.innerHTML='<span>기준</span>';}t.onclick=()=>choose(i);t.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(i);}};});if(state.prep>=2&&state.phase===3&&moves()[state.demoPos])drawArrow(el,moves()[state.demoPos]);}
function drawArrow(el,m){const f=m[0],tr={F:'translateZ(80px)',R:'rotateY(90deg) translateZ(80px)',L:'rotateY(-90deg) translateZ(80px)',B:'rotateY(180deg) translateZ(80px)',U:'rotateX(90deg) translateZ(80px)',D:'rotateX(-90deg) translateZ(80px)'}[f];el.insertAdjacentHTML('beforeend',`<div class="face-rotation" style="transform:${tr}" aria-hidden="true"><svg viewBox="0 0 100 100" style="${m.includes("'")?'transform:scaleX(-1)':''}"><path d="M26 22 A37 37 0 1 1 15 57" fill="none" stroke="#f6863f" stroke-width="6" stroke-linecap="round"/><path d="M6 63 L13 43 L27 59" fill="#f6863f"/>${m.includes('2')?'<text x="32" y="55" fill="#fff5cf" font-size="16" font-weight="bold">180°</text>':''}</svg></div>`);}
function choose(i){if(moving||loading)return;const f=FACES[Math.floor(i/9)],edge=E.some(a=>a.includes(i));if(state.prep===0){if(i%9!==4)state.feedback='가운데 한 칸인 중심을 찾아보세요.';else if(!state.hold.includes('U')&&f!=='U')state.feedback='먼저 노란 가운데 칸을 눌러 위쪽을 확인하세요.';else if(f==='U'||f==='F'){if(!state.hold.includes(f))state.hold.push(f);state.feedback=state.hold.includes('U')&&state.hold.includes('F')?'노랑은 위, 초록은 앞이에요. 실제 큐브도 같은 방향으로 잡아요.':'좋아요. 초록 중심을 눌러 앞면도 확인하세요.';}}
else if(state.prep===1){if(edge){state.edgeFound=true;state.feedback='두 색이 붙은 엣지를 찾았어요. 이 두 색은 한 조각으로 함께 움직입니다.';}else state.feedback=i%9===4?'중심은 한 색이에요. 변 가운데의 두 색 조각을 찾아보세요.':'이 조각은 세 색의 코너예요. 두 색이 붙은 엣지를 찾아보세요.';}
else if(state.phase===0){state.basis=i===FACES.indexOf(basisFace())*9+4;state.feedback=state.basis?'기준 중심을 확인했어요. 이제 그 기준과 연결할 조각을 찾아요.':'지금 볼 기준색의 가운데 칸을 찾아보세요.';}
else if(state.phase===1){state.picked=targetIndices().includes(i);state.feedback=state.picked?'맞아요. 이 색들은 한 조각으로 함께 움직여요. 다음에는 보낼 자리를 확인합니다.':i%9===4?'이건 중심이에요. 지금 옮길 엣지나 코너를 찾아주세요.':'지금 옮길 색 조합과 조각 종류를 다시 비교해보세요.';}
else if(state.phase===2){state.goalPicked=destination().includes(i);state.feedback=state.goalPicked?'보낼 자리를 확인했어요. 왜 그 면을 돌리면 이 자리로 오는지 시범으로 보세요.':'테두리로 표시한 목표 칸을 눌러 확인하세요.';}save();render();}
async function demo(){if(moving||busy||state.demoPos>=moves().length)return;moving=true;state.feedback='';await turn(model,moves()[state.demoPos],'flow-cube');state.demoPos++;moving=false;save();render();focusBoard();}
async function act(m){if(moving||busy||practiceGoal(model))return;moving=true;const before=model.asString();await turn(model,m,'flow-cube');state.history.push({before,move:m});state.practice=model.asString();state.feedback='';if(practiceGoal(model))state.feedback='목표 조각과 이미 맞춘 부분이 함께 맞았어요. 위·아래·옆 보기로 결과를 확인해보세요.';else if(state.stage===1&&model.ep[descriptor().piece]===descriptor().piece&&model.eo[descriptor().piece]===0)state.feedback='이번 엣지는 맞았지만 다른 흰 꽃잎이 내려갔어요. 목표 엣지와 남은 꽃잎을 함께 지켜야 해요. 되돌리기로 꽃잎을 복구한 뒤 다시 시도하세요.';else if(state.stage===1&&m[0]!=='U')state.feedback='반 바퀴 내린 엣지의 옆 색이 그 면 중심과 맞았나요? 다르면 되돌려 옆 색 정렬부터 확인해보세요.';else state.feedback='선택한 층의 조각들이 실제로 이동했어요. 목표 조각이 어디로 갔는지 보고, 필요하면 한 수 되돌려 다시 선택해보세요.';moving=false;save();render();}
function next(){if(moving||!nextReady())return;if(state.phase===5){state.current=model.asString();state.plan=null;if(milestone(model,state.stage)){state.completed.push(state.stage);state.stage++;}state.phase=0;state.feedback='';state.history=[];state.practice=null;if(model.isSolved())state.stage=8;save();prepare();render();window.scrollTo(0,0);return;}state.phase++;state.feedback='';view='auto';if(state.phase===3){state.demoPos=0;model=Cube.fromString(state.current);view=state.stage===1?basisFace():autoFace();state.lockedView=view;}if(state.phase===4){if(state.resumePractice){model=Cube.fromString(state.practice||state.current);view=state.practiceView||autoFace();state.resumePractice=false;}else{model=Cube.fromString(state.current);state.practice=state.current;state.history=[];view=state.stage===1?basisFace():autoFace();}state.lockedView=view;}save();render();focusBoard();}
function sourceModal(){modal(`<h2>${state.mode==='camera'?'내가 촬영한 출발 상태':'이 예제의 출발 상태'}</h2><p>현재 진도와 구분해서 보관한 최초의 6면이에요. 시범은 이 원본을 바꾸지 않으며, 직접 적용한 결과에서 수업을 이어갑니다.</p><div class="source-faces">${FACES.map((f,fi)=>`<div><b>${NAMES[f]} 중심 · ${FACE_NAMES[f]}</b><div>${[...state.initial.slice(fi*9,fi*9+9)].map(c=>`<i style="background:${COLORS[c]}"></i>`).join('')}</div></div>`).join('')}</div>`);}
function bind(){document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>switchMode(b.dataset.source));if(document.getElementById('choose-example'))document.getElementById('choose-example').onclick=()=>openExample();if(document.getElementById('source-state'))document.getElementById('source-state').onclick=sourceModal;if(document.getElementById('flow-retry'))document.getElementById('flow-retry').onclick=()=>{prepare();render();};if(document.getElementById('flow-new-example'))document.getElementById('flow-new-example').onclick=()=>openExample(0);if(!state||loading||error||state.stage>=8||!state.plan)return;decorate();document.querySelectorAll('[data-flow-view]').forEach(b=>b.onclick=()=>{if(moving)return;view=b.dataset.flowView;state.lockedView=view;save();render();focusBoard();});if(document.getElementById('flow-prep-next'))document.getElementById('flow-prep-next').onclick=()=>{state.prep++;state.feedback='';view='auto';save();render();window.scrollTo(0,0);};if(document.getElementById('flow-next'))document.getElementById('flow-next').onclick=next;if(document.getElementById('flow-demo'))document.getElementById('flow-demo').onclick=demo;document.querySelectorAll('[data-flow-face]').forEach(b=>b.onclick=()=>{if(moving)return;chosenFace=b.dataset.flowFace;render();});document.querySelectorAll('[data-flow-turn]').forEach(b=>b.onclick=()=>act(b.dataset.flowTurn));if(document.getElementById('flow-undo'))document.getElementById('flow-undo').onclick=()=>{if(moving||!state.history.length)return;model=Cube.fromString(state.history.pop().before);state.practice=model.asString();state.feedback='한 수 전으로 돌아왔어요. 조각과 목적지를 다시 비교하세요.';save();render();};if(document.getElementById('flow-more'))document.getElementById('flow-more').onclick=()=>{menu=!menu;render();};if(document.getElementById('flow-redemo'))document.getElementById('flow-redemo').onclick=()=>{if(moving)return;state.resumePractice=true;state.practiceView=view;state.phase=3;state.demoPos=0;model=Cube.fromString(state.current);view=state.stage===1?basisFace():autoFace();state.lockedView=view;state.feedback='진행 중인 큐브는 보관했어요. 지금은 이 단계의 출발 상태를 보여주는 참고 시범만 보고, 이후 방금 조작하던 상태로 돌아갑니다.';save();render();};document.querySelectorAll('[data-flow-answer]').forEach(b=>b.onclick=()=>{const q=quizzes[state.stage];state.understood=+b.dataset.flowAnswer===q.correct;state.feedback=(state.understood?'✓ 맞아요. ':'다시 관찰해볼까요? ')+q.why;save();render();});if(state.prep>=2&&[3,4].includes(state.phase))focusBoard();}
if(state)restore();
return{page,bind,position:()=>{if(state&&state.prep>=2&&[3,4].includes(state.phase))focusBoard();else window.scrollTo(0,0);},openExample,openCaptured,switchMode,start:()=>{if(!state)openExample();else{restore();routeToLesson();}},tests:{milestone,detect,read,segmentGoal}};
})();
